<?php
require __DIR__.'/lib.php';require_login();$pdo=db();$type=$_GET['type']??'';require __DIR__.'/v5_downloads.php';
if($type==='beginning_revision')beginning_review_version_download((int)($_GET['id']??0),(int)($_GET['version']??-1));
if(in_array($type,['return_template','supplier_inflow_template'],true)){$path=__DIR__.'/templates/'.($type==='return_template'?'Order_Return_Template.xlsx':'Supplier_Inflow_Template.xlsx');if(!is_file($path)){http_response_code(404);exit('Template missing. Copy the complete update.');}header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="'.basename($path).'"');readfile($path);exit;}
if($type==='order_template'){$path=__DIR__.'/templates/Standard_Order_Upload_Template.xlsx';if(!is_file($path)){http_response_code(404);exit('Order template is missing. Copy the complete update package.');}header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="Standard_Order_Upload_Template.xlsx"');header('Content-Length: '.filesize($path));readfile($path);exit;}
if($type==='generated'){$g=$_SESSION['generated_file']??null;if(!$g||!is_file($g['path']))die('Generated file is no longer available.');header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="'.basename($g['name']).'"');header('Content-Length: '.filesize($g['path']));readfile($g['path']);exit;}
if($type==='receipt'){$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT attachment_path,original_filename FROM inflow_batches WHERE id=?');$st->execute([$id]);$r=$st->fetch();$p=$r?__DIR__.'/'.$r['attachment_path']:'';if(!$r||!is_file($p))die('Attachment not found.');$ext=strtolower(pathinfo($p,PATHINFO_EXTENSION));$mime=$ext==='pdf'?'application/pdf':($ext==='png'?'image/png':($ext==='jpg'||$ext==='jpeg'?'image/jpeg':'application/octet-stream'));header('Content-Type: '.$mime);header('Content-Disposition: inline; filename="'.basename($r['original_filename']?:$p).'"');readfile($p);exit;}


if($type==='original_import'){$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT stored_path,filename FROM import_batches WHERE id=?');$st->execute([$id]);$r=$st->fetch();$p=$r?__DIR__.'/'.$r['stored_path']:'';if(!$r||!$r['stored_path']||!is_file($p))die('Original upload not found.');$ext=strtolower(pathinfo($p,PATHINFO_EXTENSION));$mime=$ext==='xlsx'?'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':'application/octet-stream';header('Content-Type: '.$mime);header('Content-Disposition: inline; filename="'.basename($r['filename']?:$p).'"');header('Content-Length: '.filesize($p));readfile($p);exit;}
if($type==='outflow_summary'){$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT * FROM import_batches WHERE id=?');$st->execute([$id]);$b=$st->fetch();if(!$b)die('Batch not found.');$q=$pdo->prepare('SELECT p.master_sku,p.name,SUM(o.qty) qty FROM outflows o JOIN products p ON p.id=o.product_id WHERE o.import_batch_id=? GROUP BY p.id,p.master_sku,p.name ORDER BY p.name');$q->execute([$id]);$posted=$q->fetchAll();$b['units']=array_sum(array_column($posted,'qty'));$rows=[['Batch ID','#'.str_pad((string)$id,6,'0',STR_PAD_LEFT)],['Date',$b['created_at']],['Platform',$b['platform']],['Original File',$b['filename']],['Total Qty Out',$b['units'].' pcs'],[],['Master SKU','Product Description','Total Qty Out']];foreach($posted as $r)$rows[]=[$r['master_sku'],$r['name'],$r['qty']];$rows[]=[];$rows[]=['','TOTAL',$b['units']];csv_download('RS8_Outflow_Batch_'.str_pad((string)$id,6,'0',STR_PAD_LEFT).'.csv',$rows);}
if($type==='import_errors'){$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT * FROM import_batches WHERE id=?');$st->execute([$id]);$b=$st->fetch();if(!$b)die('Import batch not found.');$errors=import_error_details($b);$rows=[['RS8 Import Error Report'],['Batch ID','#'.str_pad((string)$id,6,'0',STR_PAD_LEFT)],['Type',$b['import_type']],['Platform',$b['platform']],['File',$b['filename']],['Date',$b['created_at']],[],['No.','Error Type','Details','Required Action']];foreach($errors as $i=>$er){$txt=is_array($er)?json_encode($er,JSON_UNESCAPED_UNICODE):(string)$er;$low=strtolower($txt);$et=str_contains($low,'unmapped')?'Unmapped Item':(str_contains($low,'quantity')?'Invalid Quantity':(str_contains($low,'duplicate')?'Duplicate':'Validation Error'));$action=$et==='Unmapped Item'?'Map product before retrying.':($et==='Invalid Quantity'?'Correct quantity in source file.':($et==='Duplicate'?'No action if already processed.':'Review and correct source row.'));$rows[]=[$i+1,$et,$txt,$action];}csv_download('RS8_Import_Error_Report_'.str_pad((string)$id,6,'0',STR_PAD_LEFT).'.csv',$rows);}
if($type==='generated_batch'){$id=(int)($_GET['id']??0);$st=$pdo->prepare("SELECT generated_path FROM import_batches WHERE id=? AND import_type='Platform Inventory Generator'");$st->execute([$id]);$r=$st->fetch();$p=$r?__DIR__.'/'.$r['generated_path']:'';if(!$r||!is_file($p))die('Generated file not found.');header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="'.basename($p).'"');header('Content-Length: '.filesize($p));readfile($p);exit;}
if($type==='allocation_receipt'){$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT b.*,u.name user_name FROM allocation_batches b LEFT JOIN users u ON u.id=b.user_id WHERE b.id=?');$st->execute([$id]);$b=$st->fetch();if(!$b)die('Allocation batch not found.');$ln=$pdo->prepare('SELECT l.*,p.master_sku,p.name FROM allocation_lines l JOIN products p ON p.id=l.product_id WHERE l.batch_id=? ORDER BY p.brand,p.name');$ln->execute([$id]);$rows=$ln->fetchAll();receipt_header('Platform Stock Allocation Report',$b['batch_ref']);echo '<div class="meta"><div><b>Date:</b> '.e($b['created_at']).'</div><div><b>Processed by:</b> '.e($b['user_name']).'</div><div><b>Mode:</b> '.e($b['mode']).'</div><div><b>Remarks:</b> '.e($b['remarks']).'</div></div><table><tr><th>Master SKU</th><th>Product</th><th>Sellable</th><th>'.platform_label('Lazada').'</th><th>'.platform_label('Shopee').'</th><th>'.platform_label('TikTok').'</th><th>Legacy Warehouse</th></tr>';foreach($rows as $r)echo '<tr><td>'.e($r['master_sku']).'</td><td>'.e($r['name']).'</td><td>'.$r['sellable_qty'].'</td><td>'.$r['lazada_qty'].'</td><td>'.$r['shopee_qty'].'</td><td>'.$r['tiktok_qty'].'</td><td>'.$r['unallocated_qty'].'</td></tr>';echo '</table>';receipt_footer();exit;}
if($type==='transfer_receipt'){$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT t.*,p.master_sku,p.name,u.name user_name FROM platform_transfers t JOIN products p ON p.id=t.product_id LEFT JOIN users u ON u.id=t.user_id WHERE t.id=?');$st->execute([$id]);$r=$st->fetch();if(!$r)die('Transfer not found.');receipt_header('Platform Stock Transfer Receipt',$r['transfer_ref']);echo '<div class="transfer-box"><h2>'.e($r['name']).'</h2><div class="big">'.(int)$r['qty'].' pcs</div><div class="flow"><b>'.platform_label($r['from_platform']).'</b><span>→</span><b>'.platform_label($r['to_platform']).'</b></div></div><div class="meta"><div><b>Date:</b> '.e($r['txn_date']).'</div><div><b>Processed by:</b> '.e($r['user_name']).'</div><div><b>Master SKU:</b> '.e($r['master_sku']).'</div><div><b>Reason:</b> '.e($r['reason']).'</div></div>';receipt_footer();exit;}
die('Invalid download request.');
function receipt_header($title,$ref){?><!doctype html><html><head><meta charset="utf-8"><title><?=e($title)?></title><style>body{font-family:Arial,sans-serif;color:#182637;margin:36px}header{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:3px solid #ed1c24;padding-bottom:16px;margin-bottom:20px}header img{width:190px;max-height:86px;object-fit:contain;object-position:left}h1{font-size:22px;margin:0 0 5px}.ref{font-family:monospace;color:#666}.actions{position:fixed;right:22px;top:18px}@media print{.actions{display:none}body{margin:15mm}}button{background:#ed1c24;color:#fff;border:0;border-radius:8px;padding:10px 15px;font-weight:bold}.meta{display:grid;grid-template-columns:1fr 1fr;gap:8px;background:#f5f7f9;padding:14px;border-radius:10px;margin-bottom:18px;font-size:12px}table{width:100%;border-collapse:collapse;font-size:11px}th{background:#182637;color:#fff;text-align:left;padding:8px}td{border-bottom:1px solid #ddd;padding:7px}.foot{margin-top:28px;padding-top:12px;border-top:1px solid #ddd;color:#777;font-size:10px;display:flex;justify-content:space-between}.transfer-box{text-align:center;border:1px solid #ddd;border-radius:14px;padding:28px;margin-bottom:20px}.transfer-box h2{margin:0 0 10px}.big{font-size:36px;font-weight:800;color:#ed1c24}.flow{font-size:20px;display:flex;justify-content:center;gap:22px;margin-top:18px}.flow span{color:#ed1c24}</style><link rel="stylesheet" href="assets/typography.css?v=5.4.6-b"></head><body><div class="actions"><button onclick="window.print()">Print / Save as PDF</button></div><header><img src="assets/logos/rs8.png"><div><h1><?=e($title)?></h1><div class="ref"><?=e($ref)?></div></div></header><?php }
function receipt_footer(){?><div class="foot"><span>E-commerce Inventory Management System</span><span style="display:flex;align-items:center;gap:12px"><img src="assets/logos/srf.png" style="max-width:42px;max-height:18px;object-fit:contain"><img src="assets/logos/nanomoly.png" style="max-width:42px;max-height:18px;object-fit:contain"><img src="assets/logos/bossj.png" style="max-width:42px;max-height:18px;object-fit:contain"> Generated <?=date('M d, Y h:i A')?></span></div></body></html><?php }
